"use strict";

(function installNetworkTraceModel(root) {
  const ARTIFACT_SCHEMA = 2;
  const MAX_DIAGNOSTIC_STEPS = 4_096;
  const GENERATED_COMMENT =
    "// Generated by `cargo run -p kr-runtime-trace-tool --example generate_network_trace`.";
  const GENERATED_ASSIGNMENT = "globalThis.NETWORK_TRACE_DATA =";
  const OUTCOMES = new Set([
    "success",
    "rejected",
    "pending_then_completed",
    "half_closed",
    "eof",
  ]);
  const CERTAINTIES = new Set([
    "not_applied",
    "applied",
    "may_have_applied",
  ]);
  const LINK_STATES = new Set(["open", "clogged", "partitioned"]);
  const RANDOM_STREAMS = new Set([
    "schedule",
    "scenario",
    "workload",
    "fault",
    "debug",
  ]);
  const {
    exactUnsigned,
    parseJsonArtifact,
    positiveVersion,
    record,
    safeUnsigned,
    string,
  } = root.TRACE_VIEWER_CORE;

  function boolean(value, name) {
    if (typeof value !== "boolean") throw new Error(`${name} must be boolean`);
    return value;
  }

  function byteArray(value, capacity, name) {
    if (!Array.isArray(value)) throw new Error(`${name} must be an array`);
    if (value.length > capacity) {
      throw new Error(`${name} exceeds directional buffer capacity`);
    }
    return value.map((byte, index) => {
      safeUnsigned(byte, `${name}[${index}]`);
      if (byte > 255) throw new Error(`${name}[${index}] must be one byte`);
      return byte;
    });
  }

  function validateDirection(value, capacity, name) {
    const direction = record(value, name);
    const linkState = string(direction.link_state, `${name}.link_state`);
    if (!LINK_STATES.has(linkState)) {
      throw new Error(`${name}.link_state is not supported`);
    }
    return {
      bytes: byteArray(direction.bytes, capacity, `${name}.bytes`),
      senderOpen: boolean(direction.sender_open, `${name}.sender_open`),
      linkState,
    };
  }

  function validateFlow(value, capacity, name) {
    const flow = record(value, name);
    return {
      leftToRight: validateDirection(
        flow.left_to_right,
        capacity,
        `${name}.left_to_right`,
      ),
      rightToLeft: validateDirection(
        flow.right_to_left,
        capacity,
        `${name}.right_to_left`,
      ),
    };
  }

  function validateProvider(value, name) {
    const provider = record(value, name);
    return {
      listeners: safeUnsigned(provider.listeners, `${name}.listeners`),
      connections: safeUnsigned(provider.connections, `${name}.connections`),
      inflightOperations: safeUnsigned(
        provider.inflight_operations,
        `${name}.inflight_operations`,
      ),
      pendingFaults: safeUnsigned(
        provider.pending_faults,
        `${name}.pending_faults`,
      ),
      faultHits: exactUnsigned(provider.fault_hits, `${name}.fault_hits`),
    };
  }

  function validateProviderLimits(provider, config, name) {
    for (
      const [field, limit] of [
        ["listeners", config.maxListeners],
        ["connections", config.maxConnections],
        ["inflightOperations", config.maxInflightOperations],
        ["pendingFaults", config.maxScriptedFaults],
      ]
    ) {
      if (provider[field] > limit) {
        throw new Error(`${name}.${field} exceeds configured capacity`);
      }
    }
  }

  function sameDirection(left, right) {
    return left.senderOpen === right.senderOpen &&
      left.linkState === right.linkState &&
      left.bytes.length === right.bytes.length &&
      left.bytes.every((byte, index) => byte === right.bytes[index]);
  }

  function sameFlow(left, right) {
    return sameDirection(left.leftToRight, right.leftToRight) &&
      sameDirection(left.rightToLeft, right.rightToLeft);
  }

  function sameProvider(left, right) {
    return left.listeners === right.listeners &&
      left.connections === right.connections &&
      left.inflightOperations === right.inflightOperations &&
      left.pendingFaults === right.pendingFaults &&
      left.faultHits === right.faultHits;
  }

  function validateData(raw) {
    const artifact = record(raw, "network trace");
    if (artifact.schema !== ARTIFACT_SCHEMA) {
      throw new Error(
        `unsupported network trace schema ${
          String(artifact.schema)
        }; expected ${ARTIFACT_SCHEMA}`,
      );
    }
    string(artifact.scenario, "scenario");
    string(artifact.source_test, "source_test");
    string(artifact.provider, "provider");

    const startedAt = exactUnsigned(artifact.started_at_ns, "started_at_ns");
    const completedAt = exactUnsigned(
      artifact.completed_at_ns,
      "completed_at_ns",
    );
    if (completedAt < startedAt) {
      throw new Error("network trace completes before it starts");
    }

    const endpoints = record(artifact.endpoints, "endpoints");
    const leftNode = exactUnsigned(
      endpoints.left_node,
      "endpoints.left_node",
    );
    const rightNode = exactUnsigned(
      endpoints.right_node,
      "endpoints.right_node",
    );
    if (leftNode === rightNode) {
      throw new Error("network endpoints must differ");
    }

    const runtime = record(artifact.runtime, "runtime");
    positiveVersion(runtime.reproduction_schema, "runtime.reproduction_schema");
    positiveVersion(runtime.checkpoint_schema, "runtime.checkpoint_schema");
    positiveVersion(runtime.rng_version, "runtime.rng_version");
    exactUnsigned(runtime.seed, "runtime.seed");
    const maxTasks = safeUnsigned(runtime.max_tasks, "runtime.max_tasks");
    const maxTimers = safeUnsigned(runtime.max_timers, "runtime.max_timers");
    exactUnsigned(
      runtime.max_steps_per_run,
      "runtime.max_steps_per_run",
    );
    const maxTime = runtime.max_time_ns === null
      ? null
      : exactUnsigned(runtime.max_time_ns, "runtime.max_time_ns");
    const runtimeNow = exactUnsigned(runtime.now_ns, "runtime.now_ns");
    const runtimeSteps = exactUnsigned(
      runtime.total_steps,
      "runtime.total_steps",
    );
    exactUnsigned(
      runtime.next_enqueue_sequence,
      "runtime.next_enqueue_sequence",
    );
    exactUnsigned(runtime.next_timer_sequence, "runtime.next_timer_sequence");
    exactUnsigned(runtime.next_timer_id, "runtime.next_timer_id");
    const readyTasks = safeUnsigned(runtime.ready_tasks, "runtime.ready_tasks");
    const liveTimers = safeUnsigned(runtime.live_timers, "runtime.live_timers");
    const liveTasks = safeUnsigned(runtime.live_tasks, "runtime.live_tasks");
    boolean(runtime.stopped, "runtime.stopped");
    if (maxTime !== null && runtimeNow > maxTime) {
      throw new Error("runtime.now_ns exceeds runtime.max_time_ns");
    }
    if (
      liveTimers > maxTimers || liveTasks > maxTasks || readyTasks > liveTasks
    ) {
      throw new Error("runtime checkpoint counts exceed configured limits");
    }
    if (!Array.isArray(runtime.random) || runtime.random.length > 16) {
      throw new Error("runtime.random must be a bounded array");
    }
    const seenStreams = new Set();
    runtime.random.forEach((value, index) => {
      const snapshot = record(value, `runtime.random[${index}]`);
      const stream = string(snapshot.stream, `runtime.random[${index}].stream`);
      if (!RANDOM_STREAMS.has(stream) || seenStreams.has(stream)) {
        throw new Error(
          "runtime.random contains an unsupported or duplicate stream",
        );
      }
      seenStreams.add(stream);
      exactUnsigned(snapshot.state, `runtime.random[${index}].state`);
      exactUnsigned(snapshot.draws, `runtime.random[${index}].draws`);
    });
    if (runtimeNow !== completedAt) {
      throw new Error("runtime.now_ns differs from completed_at_ns");
    }

    const configValue = record(artifact.config, "config");
    const config = {
      maxListeners: safeUnsigned(
        configValue.max_listeners,
        "config.max_listeners",
      ),
      maxConnections: safeUnsigned(
        configValue.max_connections,
        "config.max_connections",
      ),
      maxInflightOperations: safeUnsigned(
        configValue.max_inflight_operations,
        "config.max_inflight_operations",
      ),
      maxScriptedFaults: safeUnsigned(
        configValue.max_scripted_faults,
        "config.max_scripted_faults",
      ),
    };
    safeUnsigned(
      configValue.max_listener_backlog,
      "config.max_listener_backlog",
    );
    safeUnsigned(
      configValue.max_operation_bytes,
      "config.max_operation_bytes",
    );
    const capacity = safeUnsigned(
      configValue.directional_buffer_bytes,
      "config.directional_buffer_bytes",
    );
    const defaultLink = record(configValue.default_link, "config.default_link");
    const maxChunk = safeUnsigned(
      defaultLink.max_chunk_bytes,
      "config.default_link.max_chunk_bytes",
    );
    if (capacity === 0 || maxChunk === 0) {
      throw new Error(
        "network buffer capacity and chunk size must be non-zero",
      );
    }
    if (maxChunk > capacity) {
      throw new Error("network max chunk exceeds directional buffer capacity");
    }
    exactUnsigned(defaultLink.latency_ns, "config.default_link.latency_ns");
    if (!LINK_STATES.has(defaultLink.state)) {
      throw new Error("config.default_link.state is not supported");
    }

    const providerStarted = validateProvider(
      artifact.provider_started,
      "provider_started",
    );
    const providerCompleted = validateProvider(
      artifact.provider_completed,
      "provider_completed",
    );
    validateProviderLimits(providerStarted, config, "provider_started");
    validateProviderLimits(providerCompleted, config, "provider_completed");
    const initialFlow = validateFlow(
      artifact.initial_flow,
      capacity,
      "initial_flow",
    );

    if (!Array.isArray(artifact.steps) || artifact.steps.length === 0) {
      throw new Error("network trace contains no diagnostic steps");
    }
    if (artifact.steps.length > MAX_DIAGNOSTIC_STEPS) {
      throw new Error(
        `network trace exceeds the ${MAX_DIAGNOSTIC_STEPS}-step viewer limit`,
      );
    }
    if (BigInt(artifact.steps.length) > runtimeSteps) {
      throw new Error("diagnostic step count exceeds runtime.total_steps");
    }
    let previousSequence = -1;
    let previousCompletion = startedAt;
    let previousProvider = providerStarted;
    let previousFlow = initialFlow;
    const steps = artifact.steps.map((candidate, index) => {
      const step = record(candidate, `step ${index}`);
      const sequence = safeUnsigned(step.sequence, `step ${index}.sequence`);
      if (sequence <= previousSequence) {
        throw new Error(
          "diagnostic presentation sequences must increase strictly",
        );
      }
      previousSequence = sequence;
      string(step.phase, `step ${sequence}.phase`);
      string(step.operation, `step ${sequence}.operation`);
      string(step.description, `step ${sequence}.description`);
      string(step.summary, `step ${sequence}.summary`);
      record(step.fields, `step ${sequence}.fields`);
      if (!OUTCOMES.has(step.outcome)) {
        throw new Error(`step ${sequence}.outcome is not supported`);
      }
      if (step.certainty !== null && !CERTAINTIES.has(step.certainty)) {
        throw new Error(`step ${sequence}.certainty is not supported`);
      }
      if ((step.outcome === "rejected") !== (step.certainty !== null)) {
        throw new Error(
          `step ${sequence} certainty must describe exactly rejected outcomes`,
        );
      }

      const stepStarted = exactUnsigned(
        step.started_at_ns,
        `step ${sequence}.started_at_ns`,
      );
      const stepCompleted = exactUnsigned(
        step.completed_at_ns,
        `step ${sequence}.completed_at_ns`,
      );
      const duration = exactUnsigned(
        step.duration_ns,
        `step ${sequence}.duration_ns`,
      );
      if (stepCompleted < stepStarted) {
        throw new Error(`step ${sequence} completes before it starts`);
      }
      if (duration !== stepCompleted - stepStarted) {
        throw new Error(
          `step ${sequence} duration does not match its interval`,
        );
      }
      if (stepStarted < previousCompletion) {
        throw new Error(`step ${sequence} overlaps the prior step`);
      }
      if (stepCompleted > completedAt) {
        throw new Error(`step ${sequence} completes after the scenario`);
      }

      const providerBefore = validateProvider(
        step.provider_before,
        `step ${sequence}.provider_before`,
      );
      const providerAfter = validateProvider(
        step.provider_after,
        `step ${sequence}.provider_after`,
      );
      validateProviderLimits(
        providerBefore,
        config,
        `step ${sequence}.provider_before`,
      );
      validateProviderLimits(
        providerAfter,
        config,
        `step ${sequence}.provider_after`,
      );
      const flowBefore = validateFlow(
        step.flow_before,
        capacity,
        `step ${sequence}.flow_before`,
      );
      const flowAfter = validateFlow(
        step.flow_after,
        capacity,
        `step ${sequence}.flow_after`,
      );
      if (!sameProvider(providerBefore, previousProvider)) {
        throw new Error(`step ${sequence} provider state is discontinuous`);
      }
      if (!sameFlow(flowBefore, previousFlow)) {
        throw new Error(`step ${sequence} duplex state is discontinuous`);
      }
      if (
        step.certainty === "not_applied" &&
        (!sameProvider(providerBefore, providerAfter) ||
          !sameFlow(flowBefore, flowAfter))
      ) {
        throw new Error(
          `step ${sequence} marked not_applied changed observable state`,
        );
      }

      previousCompletion = stepCompleted;
      previousProvider = providerAfter;
      previousFlow = flowAfter;
      return {
        ...step,
        _startedAt: stepStarted,
        _completedAt: stepCompleted,
        _duration: duration,
        _outcome: step.outcome === "rejected" ? "rejected" : "success",
        _providerBefore: providerBefore,
        _providerAfter: providerAfter,
        _flowBefore: flowBefore,
        _flowAfter: flowAfter,
      };
    });

    if (previousCompletion !== completedAt) {
      throw new Error("final step completion differs from completed_at_ns");
    }
    if (!sameProvider(previousProvider, providerCompleted)) {
      throw new Error("final provider state differs from provider_completed");
    }

    return {
      raw: artifact,
      steps,
      capacity,
      endpoints: { left: leftNode, right: rightNode },
    };
  }

  function parseArtifactText(text) {
    return parseJsonArtifact(text, {
      assignment: GENERATED_ASSIGNMENT,
      generatedComment: GENERATED_COMMENT,
      description: "network trace",
    });
  }

  root.NETWORK_TRACE_MODEL = Object.freeze({
    artifactSchema: ARTIFACT_SCHEMA,
    parseArtifactText,
    validateData,
  });
})(globalThis);
